const request = async (url, fetchImpl = globalThis.fetch, capturedAt = null, { retries = 3, retryDelayMs = 250, fixtureOnly = false } = {}) => { if (typeof fetchImpl !== 'function') throw new Error('fetch implementation is required'); if (capturedAt !== null && !fixtureOnly) throw new Error('caller-supplied capturedAt is fixture-only; production source custody uses the observed response/call time'); let lastError; for (let attempt = 0; attempt <= retries; attempt++) { try { const response = await fetchImpl(url, { headers: { accept: 'application/json' } }); if (!response.ok) throw new Error(`public adapter HTTP ${response.status}: ${url}`); const body = Buffer.from(await response.arrayBuffer()); const observedAt = new Date().toISOString(); const headerDate = response.headers?.get?.('date'); const responseObservedAt = headerDate && Number.isFinite(Date.parse(headerDate)) ? new Date(Date.parse(headerDate)).toISOString() : observedAt; return { body, json: JSON.parse(body.toString('utf8')), retrieved_at: fixtureOnly && capturedAt ? capturedAt : responseObservedAt, observed_at: responseObservedAt, capture_time_source: fixtureOnly && capturedAt ? 'FIXTURE_SUPPLIED' : 'CALL_OBSERVED', status: response.status } } catch (error) { lastError = error; if (attempt < retries && retryDelayMs > 0) await new Promise(resolve => setTimeout(resolve, retryDelayMs * (attempt + 1))) } } throw lastError }
