const capture = (adapter, requestInfo, response, rows) => ({ schema: 'public-data-capture/1', adapter_id: adapter.adapter_id, adapter_code_sha256: ADAPTER_CODE_SHA256, pit_tier: adapter.pit_tier, pit_provenance: adapter.pit_provenance || null, revision_status: adapter.revision_status || null, request: requestInfo, response_sha256: createHash('sha256').update(response.body).digest('hex'), response_body: Buffer.from(response.body), captured_at: response.retrieved_at, observed_at: response.observed_at, capture_time_source: response.capture_time_source, rows: rows.map(row => ({ ...row, adapter_code_sha256: ADAPTER_CODE_SHA256, pit_tier: row.pit_tier || adapter.pit_tier, pit_provenance: row.pit_provenance || adapter.pit_provenance || null, revision_status: row.revision_status || adapter.revision_status || null })) })

